cat > src/parse.js <<'EOF'
function fail(msg) {
  const e = new Error(msg)
  e.parseError = true
  throw e
}

export function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  let candidates = null
  let sawBallot = false
  const ballots = []
  for (let i = 0; i < lines.length; i++) {
    const n = i + 1
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const words = line.split(/\s+/)
    const head = words[0]
    const err = (m) => fail(`error: line ${n}: ${m}`)
    if (head === 'candidates') {
      if (candidates !== null || sawBallot) err('candidates must be declared once, before any ballot')
      if (words.length < 2) err('expected candidates <name>...')
      const seen = new Set()
      for (const w of words.slice(1)) {
        if (!/^[A-Za-z0-9_-]+$/.test(w)) err(`invalid candidate name ${w}`)
        if (seen.has(w)) err(`candidate ${w} is declared twice`)
        seen.add(w)
      }
      candidates = [...seen]
    } else if (head === 'ballot') {
      sawBallot = true
      if (words.length < 3) err('expected ballot <count> <candidate>...')
      if (!/^[1-9][0-9]*$/.test(words[1])) err('count must be a positive integer')
      const known = new Set(candidates || [])
      const seen = new Set()
      for (const w of words.slice(2)) {
        if (!known.has(w)) err(`unknown candidate ${w}`)
        if (seen.has(w)) err(`candidate ${w} is repeated`)
        seen.add(w)
      }
      ballots.push({ count: BigInt(words[1]), ranking: words.slice(2) })
    } else {
      err(`unknown directive ${head}`)
    }
  }
  if (candidates === null) fail('error: no candidates')
  return { candidates, ballots }
}
EOF
cat > src/count.js <<'EOF'
export function count({ candidates, ballots }) {
  const continuing = new Set(candidates)
  const history = new Map(candidates.map((c) => [c, []]))
  const rounds = []
  for (;;) {
    const votes = new Map([...continuing].map((c) => [c, 0n]))
    let active = 0n
    for (const b of ballots) {
      const pick = b.ranking.find((c) => continuing.has(c))
      if (pick !== undefined) {
        votes.set(pick, votes.get(pick) + b.count)
        active += b.count
      }
    }
    let total = 0n
    for (const b of ballots) total += b.count
    for (const [c, v] of votes) history.get(c).push(v)
    const list = [...votes].sort((a, b) => (a[1] > b[1] ? -1 : a[1] < b[1] ? 1 : a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0))
    const round = { list: list.map(([n, v]) => [n, v.toString()]), exhausted: (total - active).toString(), eliminated: null }
    rounds.push(round)
    if (active === 0n) return { rounds, winner: null }
    for (const [c, v] of votes) if (v * 2n > active) return { rounds, winner: c }
    let tied = [...votes.keys()]
    const len = rounds.length
    for (let r = 0; r < len && tied.length > 1; r++) {
      let min = null
      for (const c of tied) {
        const v = history.get(c)[r]
        if (min === null || v < min) min = v
      }
      tied = tied.filter((c) => history.get(c)[r] === min)
    }
    tied.sort()
    const out = tied[tied.length - 1]
    continuing.delete(out)
    round.eliminated = out
  }
}
EOF
